<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1"><title>Log in — PawTalaan</title><script>(()=>{const mobile=/Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);const update=()=>{const tablet=mobile&&Math.min(innerWidth,innerHeight)>=480;document.documentElement.classList.toggle('phone-device',mobile&&!tablet);document.documentElement.classList.toggle('tablet-device',tablet);document.documentElement.classList.toggle('mobile-landscape',mobile&&innerWidth>innerHeight)};update();addEventListener('resize',update);addEventListener('orientationchange',update)})()</script><link rel="stylesheet" href="/assets/login-mobile-4.css?v=23">
<style>
